api-design.method-signature:
// Existing method (no signature change)
pub fn add_document(&mut self, doc_id: DocId, text: &str) -> Result<(), PipelineError>

// New internal method (private)
fn bloom_pre_check(&self, doc_id: DocId, text: &str) -> bool

api-design.statistics-api:
// New public methods (backward compatible)
pub fn documents_skipped(&self) -> usize
pub fn skip_rate(&self) -> f64  // Bloom hit rate (0.0 to 1.0)

exact-duplicates.code:
// SEQUENTIAL (5% of corpus, 10 clusters)
for cluster_id in 0..10 {
    let template = format!("Exact duplicate cluster {} ...", cluster_id);
    for doc_idx in 0..cluster_size {
        corpus.push(Document { ... });
    }
}

near-duplicates.code:
// PARALLEL (15% of corpus, rayon)
let near_docs: Vec<Document> = near_indices
    .into_par_iter()
    .map(|(cluster_id, doc_idx)| { ... })
    .collect();
corpus.extend(near_docs);

unique-documents.code:
// PARALLEL (80% of corpus, rayon)
let unique_docs: Vec<Document> = unique_indices
    .into_par_iter()
    .map(|i| { ... })
    .collect();
corpus.extend(unique_docs);

exact-duplicates.code:
// PARALLEL (5% of corpus, rayon)
let exact_indices: Vec<(usize, usize)> = (0..10)
    .flat_map(|cluster_id| {
        (0..cluster_size).map(move |doc_idx| (cluster_id, doc_idx))
    })
    .collect();

let exact_docs: Vec<Document> = exact_indices
    .into_par_iter()
    .map(|(cluster_id, doc_idx)| {
        let doc_id = cluster_id * cluster_size + doc_idx;
        let template = format!(
            "Exact duplicate cluster {} containing machine learning neural network data analysis",
            cluster_id
        );
        Document {
            id: doc_id,
            url: format!("https://example.com/doc/{}", doc_id),
            text: template,
        }
    })
    .collect();

corpus.extend(exact_docs);
